192	describe('the conversation list on the websocket', () => {
193	  it("delivers the connecting user's conversations as one conversation_list, newest first, with wire times as ISO strings", async () => {
194	    const store = new InMemorySessionStore();
195	    const url = await startConfiguredEngine({
196	      provider: {type: 'mock'},
197	      prompt: {identity: 'test'},
198	      session: store,
199	      auth: {ws: async () => ({id: USER})},
200	      transport: {history: {enabled: true}},
201	    });
202	    const {client, seen, sessionId} = await openAndSettle(url);
203	    seed(store, 'earlier', USER, JAN);
204	    seed(store, 'later', USER, FEB);
205	    seed(store, 'someone-elses', SOMEONE_ELSE, FEB);
206	
207	    const beforeRequest = seen.length;
208	    client.send(JSON.stringify({type: 'list_conversations'}));
209	    await until(
210	      seen,
211	      frame => frame.type === 'conversation_list' || frame.type === 'error',
212	      'the answer to the list request'
213	    );
214	    await settle(client, seen);
215	
216	    const lists = seen.filter(frame => frame.type === 'conversation_list');
217	    const rows = lists[0]?.conversations ?? [];
218	    const timesAreIso = rows.every(row => ISO.test(row.createdAt) && ISO.test(row.updatedAt));
219	
220	    expect({
221	      pushedBeforeAnyoneAsked: seen.slice(0, beforeRequest).some(frame => frame.type === 'conversation_list'),
222	      answered: lists.length,
223	      withErrors: seen.filter(frame => frame.type === 'error').map(frame => frame.code),
224	      newestFirst: rows.map(row => row.sessionId),
225	      theConversationItSitsIn: {row: rows[0]?.sessionId, entries: rows[0]?.entryCount},
226	      timesAreIso,
227	      closesLikeATurn: seen.some(frame => frame.type === 'stream_end'),
228	    }).toEqual({
229	      pushedBeforeAnyoneAsked: false,
230	      answered: 1,
231	      withErrors: [],
232	      newestFirst: [sessionId, 'later', 'earlier'],
233	      theConversationItSitsIn: {row: sessionId, entries: 0},
234	      timesAreIso: true,
235	      closesLikeATurn: false,
236	    });
237	  });
238	
239	  it("answers a frame naming another user with the connecting user's own list, paging by the window the frame sent", async () => {
240	    const store = new RecordingStore();
241	    const url = await startEngine({sessionStore: store, history: {enabled: true}});
242	    const {client, seen} = await openAndSettle(url);
243	    seed(store, 'older', USER, JAN);
244	    seed(store, 'middle', USER, FEB);
245	    seed(store, 'newest', USER, MARCH);
246	    seed(store, 'someone-elses', SOMEONE_ELSE, MARCH);
247	
248	    client.send(JSON.stringify({type: 'list_conversations', userId: SOMEONE_ELSE, limit: 1}));
249	    const first = await until(
250	      seen,
251	      frame => frame.type === 'conversation_list' || frame.type === 'error',
252	      'a first page'
253	    );
254	    const [head] = first.conversations ?? [];
255	    client.send(
256	      JSON.stringify({
257	        type: 'list_conversations',
258	        userId: SOMEONE_ELSE,
259	        limit: 1,
260	        before: {updatedAt: head?.updatedAt, sessionId: head?.sessionId},
261	      })
262	    );
263	    await until(
264	      seen,
265	      frame => (frame.type === 'conversation_list' && frame !== first) || frame.type === 'error',
266	      'a second page'
267	    );
268	    await settle(client, seen);
269	
270	    const pages = seen
271	      .filter(frame => frame.type === 'conversation_list')
272	      .map(frame => (frame.conversations ?? []).map(row => row.sessionId));
273	    const asked = store.asked.map(call => ({
274	      userId: call.userId,
275	      limit: call.options?.limit,
276	      before: call.options?.before,
277	    }));
278	
279	    expect({pages, asked}).toEqual({
280	      pages: [['newest'], ['middle']],
281	      asked: [
282	        {userId: USER, limit: 1, before: undefined},
283	        {userId: USER, limit: 1, before: {updatedAt: MARCH, sessionId: 'newest'}},
284	      ],
285	    });
286	  });
287	
288	  it('answers UNSUPPORTED wherever it cannot answer, and never with a list or an empty one', async () => {
289	    // Off by default: the deployer never turned history on.
290	    const off = await startEngine({sessionStore: storeHolding([['kept', USER, JAN]])});
291	    const refused = await openAndSettle(off);
292	    refused.client.send(JSON.stringify({type: 'list_conversations'}));
293	    await until(refused.seen, frame => frame.type === 'error', 'the answer to a refused list');
294	    await settle(refused.client, refused.seen);
295	
296	    // On, against a store written before lists existed: it has no listFor to answer with.
297	    const withoutListFor = await startEngine({sessionStore: fiveMemberStore, history: {enabled: true}});
298	    const unlisted = await openAndSettle(withoutListFor);
299	    unlisted.client.send(JSON.stringify({type: 'list_conversations'}));
300	    await until(unlisted.seen, frame => frame.type === 'error', 'the answer over a store that cannot list');
301	    await settle(unlisted.client, unlisted.seen);
302	
303	    const answered = (seen: Frame[]): {codes: string[]; lists: number; rows: number} => ({
304	      codes: seen.filter(frame => frame.type === 'error').map(frame => frame.code),
305	      lists: seen.filter(frame => frame.type === 'conversation_list').length,
306	      rows: seen.filter(frame => frame.type === 'conversation_list').flatMap(frame => frame.conversations ?? []).length,
307	    });
308	
309	    expect({offByDefault: answered(refused.seen), withoutAListFor: answered(unlisted.seen)}).toEqual({
310	      offByDefault: {codes: ['UNSUPPORTED'], lists: 0, rows: 0},
311	      withoutAListFor: {codes: ['UNSUPPORTED'], lists: 0, rows: 0},
312	    });
313	  });
314	
315	  it('answers UNSUPPORTED for a store that throws StoreCannotList, as the misconfiguration it is', async () => {
316	    const url = await startEngine({sessionStore: new CannotListStore(), history: {enabled: true}});
317	    const {client, seen} = await openAndSettle(url);
318	    client.send(JSON.stringify({type: 'list_conversations'}));
319	    await until(seen, frame => frame.type === 'error', 'the answer to a misconfigured store');
320	    await settle(client, seen);
321	
322	    expect({
323	      codes: seen.filter(frame => frame.type === 'error').map(frame => frame.code),
324	      lists: seen.filter(frame => frame.type === 'conversation_list').length,
325	    }).toEqual({codes: ['UNSUPPORTED'], lists: 0});
326	  });
