328	  it('answers SERVER_ERROR when the store fails, without carrying its detail, and keeps the socket', async () => {
329	    // Captured for this test alone: the criterion is the log line written beside the frame.
330	    const logged: Array<Record<string, unknown>> = [];
331	    setLogger({
332	      debug: () => undefined,
333	      info: () => undefined,
334	      warn: () => undefined,
335	      error: (category, message, fields) => void logged.push({category, message, ...fields}),
336	    });
337	    try {
338	      const url = await startEngine({sessionStore: new FailingStore(), history: {enabled: true}});
339	      const {client, seen, sessionId} = await openAndSettle(url);
340	      client.send(JSON.stringify({type: 'list_conversations'}));
341	      await until(seen, frame => frame.type === 'error', 'the answer to a failing store');
342	      // The ping after the failure is answered only on a socket the error did not close.
343	      await settle(client, seen);
344	
345	      const answered = seen
346	        .filter(frame => frame.type === 'error')
347	        .map(frame => ({code: frame.code, carriesStoreDetail: /db-prod|mongo|cluster/.test(frame.message ?? '')}));
348	
349	      expect({
350	        answered,
351	        logged: {
352	          withSession: logged.some(line => line.sessionId !== undefined),
353	          storeDetail: logged.some(line => JSON.stringify(line).includes('db-prod')),
354	        },
355	      }).toEqual({
356	        answered: [{code: 'SERVER_ERROR', carriesStoreDetail: false}],
357	        logged: {withSession: true, storeDetail: false},
358	      });
359	    } finally {
360	      setLogger(SILENT);
361	    }
362	  });
363	
364	  it("answers a list request while a turn streams, before that turn's stream_end", async () => {
365	    const hold = deferred();
366	    const streaming: ChatOrchestrator = {
367	      processMessage: async () => 'hi',
368	      async *processMessageStream(): AsyncGenerator<MessageChunk> {
369	        yield {type: 'text', text: 'half an answer'};
370	        await hold.until;
371	        yield {type: 'stop', stopReason: 'end_turn'};
372	      },
373	    };
374	    const url = await startEngine({sessionStore: new InMemorySessionStore(), history: {enabled: true}}, streaming);
375	    const {client, seen} = await openAndSettle(url);
376	
377	    client.send(JSON.stringify({type: 'user_message', content: 'a question worth a long answer'}));
378	    await until(seen, frame => frame.type === 'entry_delta', 'the streaming answer to start');
379	    client.send(JSON.stringify({type: 'list_conversations'}));
380	    await until(
381	      seen,
382	      frame => frame.type === 'conversation_list' || frame.type === 'error',
383	      'the answer to the list request'
384	    );
385	    hold.release();
386	    await until(seen, frame => frame.type === 'stream_end', 'the turn to end');
387	
388	    const order = seen.map(frame => frame.type);
389	    expect({
390	      listBeforeStreamEnd: order.indexOf('conversation_list') < order.indexOf('stream_end'),
391	      answers: seen
392	        .filter(frame => frame.type === 'conversation_list')
393	        .map(frame => (frame.conversations ?? []).length),
394	    }).toEqual({listBeforeStreamEnd: true, answers: [1]});
395	  });
