397	  it('refuses a frame whose window is malformed, naming the field', async () => {
398	    const url = await startEngine({sessionStore: new InMemorySessionStore(), history: {enabled: true}});
399	    const {client, seen} = await openAndSettle(url);
400	
401	    const malformed = [
402	      {type: 'list_conversations', limit: 0},
403	      {type: 'list_conversations', limit: 201},
404	      {type: 'list_conversations', limit: 1.5},
405	      {type: 'list_conversations', limit: '10'},
406	      {type: 'list_conversations', before: 'not a date'},
407	      {type: 'list_conversations', before: {updatedAt: JAN}},
408	    ];
409	    for (const frame of malformed) client.send(JSON.stringify(frame));
410	    await settle(client, seen);
411	
412	    const refusals = seen
413	      .filter(frame => frame.type === 'error')
414	      .map(frame => ({
415	        code: frame.code,
416	        names: ['limit', 'before'].find(field => (frame.message ?? '').includes(field)),
417	      }));
418	
419	    expect(refusals).toEqual([
420	      {code: 'INVALID_MESSAGE', names: 'limit'},
421	      {code: 'INVALID_MESSAGE', names: 'limit'},
422	      {code: 'INVALID_MESSAGE', names: 'limit'},
423	      {code: 'INVALID_MESSAGE', names: 'limit'},
424	      {code: 'INVALID_MESSAGE', names: 'before'},
425	      {code: 'INVALID_MESSAGE', names: 'before'},
426	    ]);
427	  });
