429	  it('rejoins a conversation by an id taken from the list, through the resume path resume enables', async () => {
430	    const url = await startEngine({
431	      sessionStore: storeHolding([
432	        ['stored-one', USER, JAN],
433	        ['stored-two', USER, FEB],
434	      ]),
435	      resume: {enabled: true},
436	      history: {enabled: true},
437	    });
438	    const {client, seen} = await openAndSettle(url);
439	    client.send(JSON.stringify({type: 'list_conversations'}));
440	    const listed = await until(
441	      seen,
442	      frame => frame.type === 'conversation_list' || frame.type === 'error',
443	      'the conversation list'
444	    );
445	    const row = (listed.conversations ?? []).find(candidate => candidate.sessionId === 'stored-one');
446	
447	    client.close();
448	    await once(client, 'close');
449	    const again = await openAndSettle(`${url}?sessionId=${row?.sessionId}`);
450	    await settle(again.client, again.seen);
451	
452	    expect({
453	      tookTheIdFrom: row?.sessionId,
454	      resumed: again.seen[0]?.resumed,
455	      entryCount: again.seen[0]?.entryCount,
456	      replay: again.seen.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry?.content),
457	    }).toEqual({
458	      tookTheIdFrom: 'stored-one',
459	      resumed: true,
460	      entryCount: 1,
461	      replay: ['what stored-one asked'],
462	    });
463	  });
464	});
